function fib(n: nat): nat
  decreases n
{
  if n == 0 then 0
  else if n == 1 then 1
  else fib(n - 1) + fib(n - 2)
}
// pure-end
method ComputeFib(n: nat) returns (result: nat)
  // post-conditions-start
  ensures result == fib(n)
  // post-conditions-end
{
  // impl-start
  var i: nat := 0;
  var a: nat := 0;
  var b: nat := 1;
  while i < n
    invariant 0 <= i <= n
    invariant a == fib(i)
    invariant b == fib(i + 1)
    decreases n - i
  {
    var c: nat := a + b;
    a := b;
    b := c;
    i := i + 1;
  }
  result := a;
  // impl-end
}

