052-below-threshold.final_code:
method below_threshold(l : seq<int>, t : int) returns (b : bool)
    // post-conditions-start
    ensures b == (forall i : int :: i >= 0 && i < |l| ==> l[i] < t)
    // post-conditions-end
{
    b := true;
    var i := 0;
    while i < |l|
      invariant 0 <= i <= |l|
      invariant forall j : int :: 0 <= j && j < i ==> l[j] < t
      decreases |l| - i
    {
        b := b && (l[i] < t);
        i := i + 1;
    }
}

