method is_array_sorted(s: seq<int>) returns (sorted: bool)
  // pre-conditions-start
  // pre-conditions-end
  // post-conditions-start
  ensures sorted <==> forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
  // post-conditions-end
{
  // impl-start
  var i := 0;
  while i < |s|
    invariant 0 <= i <= |s|
    invariant forall a, b :: 0 <= a < i && a < b < |s| ==> s[a] <= s[b]
    decreases |s| - i
  {
    var j := i + 1;
    while j < |s|
      invariant i < j <= |s|
      invariant forall b :: i < b < j ==> s[i] <= s[b]
      decreases |s| - j
    {
      if s[i] > s[j] {
        assert 0 <= i < j < |s| && s[i] > s[j];
        assert !(forall a, b :: 0 <= a < b < |s| ==> s[a] <= s[b]);
        sorted := false;
        return;
      }
      j := j + 1;
    }
    assert j == |s|;
    assert forall b :: i < b < |s| ==> s[i] <= s[b];
    i := i + 1;
  }
  assert i == |s|;
  assert forall a, b :: 0 <= a < b < |s| ==> s[a] <= s[b];
  sorted := true;
  // impl-end
}

