all_unique.final_code:
method all_unique(s: seq<int>) returns (unique: bool)
  ensures unique <==> forall i, j :: 0 <= i < j < |s| ==> s[i] != s[j]
{
  var i := 0;
  while i < |s|
    invariant 0 <= i <= |s|
    invariant forall a, b :: 0 <= a < i && a < b < |s| ==> s[a] != s[b]
    decreases |s| - i
  {
    var j := i + 1;
    while j < |s|
      invariant i < j <= |s|
      invariant forall b :: i < b < j ==> s[i] != s[b]
      decreases |s| - j
    {
      if s[i] == s[j] {
        unique := false;
        assert 0 <= i < j < |s| && s[i] == s[j];
        assert exists a, b :: 0 <= a < b < |s| && s[a] == s[b];
        assert !(forall a, b :: 0 <= a < b < |s| ==> s[a] != s[b]);
        return;
      }
      j := j + 1;
    }
    assert j == |s|;
    assert forall b :: i < b < |s| ==> s[i] != s[b];
    assert forall a, b :: 0 <= a < i + 1 && a < b < |s| ==> s[a] != s[b];
    i := i + 1;
  }
  assert i == |s|;
  assert forall a, b :: 0 <= a < b < |s| ==> s[a] != s[b];
  unique := true;
  return;
