    assert forall b :: i < b < |s| ==> s[i] != s[b];
    assert forall a, b :: 0 <= a < i + 1 && a < b < |s| ==> s[a] != s[b];
    i := i + 1;
  }
  assert i == |s|;
  assert forall a, b :: 0 <= a < b < |s| ==> s[a] != s[b];
  unique := true;
  return;
}

